import{_ as n,C as l,o as s,c as r,a2 as a,b as o,w as t,a as d,E as h,a3 as p}from"./chunks/framework.CZqXuAiL.js";const F=JSON.parse('{"title":"Kernel Feature Gates","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/architecture/kernel-gates.md","filePath":"openshield-xdp/architecture/kernel-gates.md","lastUpdated":1783232968000}'),k={name:"openshield-xdp/architecture/kernel-gates.md"};function c(g,e,u,b,E,y){const i=l("Mermaid");return s(),r("div",null,[e[1]||(e[1]=a(`<h1 id="kernel-feature-gates" tabindex="-1">Kernel Feature Gates <a class="header-anchor" href="#kernel-feature-gates" aria-label="Permalink to &quot;Kernel Feature Gates&quot;">​</a></h1><p>OpenShield-XDP uses <strong>compile-time feature gates</strong> to enable or disable functionality based on the running kernel version. This allows a single codebase to support kernels from 5.15 through 6.10+ while leveraging newer BPF features when available.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>The top-level <code>Makefile</code> detects the running kernel version via <code>uname -r</code> and sets C preprocessor defines (<code>-D</code> flags) passed to both the eBPF compiler (clang) and the Go binding generator (bpf2go):</p><div class="language-makefile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">makefile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Makefile (top-level)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KERNEL_VER := </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uname -r | cut -d. -f1,2)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KERNEL_MAJOR := </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">word</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1,$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">subst</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ., ,$(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KERNEL_VER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KERNEL_MINOR := </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">word</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2,$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">subst</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ., ,$(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KERNEL_VER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)))</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BPF_FEATURES := -D__TARGET_ARCH_x86 -D_GNU_SOURCE</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Feature-specific gates added conditionally...</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Build-time only</p><p>Feature gates are evaluated at <strong>build time</strong>, not at runtime. If you upgrade your kernel, you must <strong>rebuild</strong> OpenShield-XDP to enable newly available features. Running <code>uname -r</code> during the build determines what gets compiled in.</p></div><h2 id="feature-gates" tabindex="-1">Feature Gates <a class="header-anchor" href="#feature-gates" aria-label="Permalink to &quot;Feature Gates&quot;">​</a></h2><h3 id="openshield-synproxy" tabindex="-1"><code>OPENSHIELD_SYNPROXY</code> <a class="header-anchor" href="#openshield-synproxy" aria-label="Permalink to &quot;\`OPENSHIELD_SYNPROXY\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Minimum kernel</strong></td><td>5.15 (baseline minimum, not a special requirement)</td></tr><tr><td><strong>Detection</strong></td><td><code>test $(KERNEL_MAJOR) -gt 5 -o \\( $(KERNEL_MAJOR) -eq 5 -a $(KERNEL_MINOR) -ge 15 \\)</code></td></tr><tr><td><strong>What it gates</strong></td><td>Scalar, non-terminal SYN classification gate (rate-based)</td></tr><tr><td><strong>Compiles to</strong></td><td><code>synproxy_check_listener()</code> — a scalar-only <code>__always_inline</code> hook</td></tr><tr><td><strong>Below threshold</strong></td><td>Compiles out entirely — SYN handling falls back to the rate limiter</td></tr></tbody></table><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// openshield.bpf.c</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#ifdef</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OPENSHIELD_SYNPROXY</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">synproxy_check_listener</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, cfg) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> STAGE_DROP)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> XDP_DROP;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#endif</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> /* OPENSHIELD_SYNPROXY */</span></span></code></pre></div><p><strong>Why scalar-only?</strong> The gate reads <strong>only</strong> pre-parsed scalar fields from <code>packet_info</code> — no packet-pointer access and no version-specific helpers (no <code>bpf_sk_lookup_tcp</code>, no cookie crypto, no <code>XDP_TX</code>). This guarantees it verifies and loads on <strong>every</strong> supported kernel (5.15 → latest) with zero user fixes. Actual SYN-flood mitigation is delivered by the per-IP <code>syn_pps_threshold</code> rate limiter. On kernels ≥ 6.10 an <strong>opt-in</strong> freplace module can hot-patch this hook to add richer listener verification.</p><h3 id="l7-signatures-—-not-gated-all-16-slots-every-kernel" tabindex="-1">L7 signatures — not gated (all 16 slots, every kernel) <a class="header-anchor" href="#l7-signatures-—-not-gated-all-16-slots-every-kernel" aria-label="Permalink to &quot;L7 signatures — not gated (all 16 slots, every kernel)&quot;">​</a></h3><p>The L7 signature matcher is <strong>not</strong> behind a kernel gate. It always compiles a single <code>#pragma unroll</code> loop over all 16 slots of <code>l7_sig_map</code>, and this verifies and loads on every supported kernel from 5.15. There is no &quot;slot 0 only&quot; mode.</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// openshield.bpf.c — always compiled, all kernels</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#pragma</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> unroll</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (u32 i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; i</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">++</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> /* check l7_sig_map[i] */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Earlier builds shipped an <code>OPENSHIELD_L7_MULTISLOT</code> flag intended to gate slots 1-15 at kernel 6.10. The flag was never referenced by the BPF source (the loop was always 16 slots), so it has been removed to avoid a misleading, dead build gate. L7 protection is identical on every supported kernel.</p></div><h3 id="openshield-global-detect" tabindex="-1"><code>OPENSHIELD_GLOBAL_DETECT</code> <a class="header-anchor" href="#openshield-global-detect" aria-label="Permalink to &quot;\`OPENSHIELD_GLOBAL_DETECT\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Minimum kernel</strong></td><td>6.10</td></tr><tr><td><strong>Detection</strong></td><td><code>test $(KERNEL_MAJOR) -gt 6 -o \\( $(KERNEL_MAJOR) -eq 6 -a $(KERNEL_MINOR) -ge 10 \\)</code></td></tr><tr><td><strong>What it gates</strong></td><td>SYN/FIN ratio detection + entropy spoofing detection</td></tr><tr><td><strong>Compiles to</strong></td><td><code>check_global_detection()</code> function call</td></tr><tr><td><strong>Below threshold</strong></td><td>No-op — global detection stage skipped</td></tr></tbody></table><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#ifdef</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OPENSHIELD_GLOBAL_DETECT</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    check_global_detection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(cfg, now);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#endif</span></span></code></pre></div><p><strong>Why kernel ≥ 6.10?</strong> Global detection uses <code>bpf_for_each_map_elem</code> for iterating entropy buckets and SYN/FIN counters, which requires kernel 5.13+. The 6.10 gate is conservative — it also covers the combined verifier complexity of global detection + entropy together.</p><h3 id="openshield-entropy" tabindex="-1"><code>OPENSHIELD_ENTROPY</code> <a class="header-anchor" href="#openshield-entropy" aria-label="Permalink to &quot;\`OPENSHIELD_ENTROPY\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>Minimum kernel</strong></td><td>6.10</td></tr><tr><td><strong>Detection</strong></td><td>Same combined check as <code>OPENSHIELD_GLOBAL_DETECT</code></td></tr><tr><td><strong>What it gates</strong></td><td>Per-packet entropy bucket updates</td></tr><tr><td><strong>Compiles to</strong></td><td><code>update_entropy_bucket()</code> function call</td></tr><tr><td><strong>Below threshold</strong></td><td>No-op</td></tr></tbody></table><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#ifdef</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OPENSHIELD_ENTROPY</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    update_entropy_bucket</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#endif</span></span></code></pre></div><p><strong>Why kernel ≥ 6.10?</strong> Per-packet entropy tracking uses <code>bpf_get_prandom_u32()</code> for bucket selection and requires spinlock-free per-CPU hash bucket updates. The verifier in older kernels would reject the complexity.</p><h2 id="feature-gate-summary" tabindex="-1">Feature Gate Summary <a class="header-anchor" href="#feature-gate-summary" aria-label="Permalink to &quot;Feature Gate Summary&quot;">​</a></h2>`,24)),(s(),o(p,null,{default:t(()=>[h(i,{id:"mermaid-219",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20K515%5B%22Kernel%20%E2%89%A5%205.15%20(baseline)%3Cbr%2F%3EFull%20core%20pipeline%3Cbr%2F%3EScalar%20rate-based%20SYNPROXY%3Cbr%2F%3E16-slot%20L7%20always%20compiled%22%5D%0A%20%20%20%20K610%5B%22Kernel%20%E2%89%A5%206.10%3Cbr%2F%3EGlobal%20Detection%3A%20SYN%2FFIN%20ratio%20%2B%20entropy%3Cbr%2F%3EEntropy%20Analysis%3A%20per-packet%20bucket%20tracking%3Cbr%2F%3Efreplace%20hot-patching%20(opt-in%3A%20make%20FREPLACE%3D1)%22%5D%0A%20%20%20%20K515%20--%3E%20K610%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<table tabindex="0"><thead><tr><th>Feature Gate</th><th>Kernel</th><th>Feature</th></tr></thead><tbody><tr><td><em>(none required)</em></td><td>5.15+</td><td>Core pipeline: MAC filter, parse, panic breaker, whitelist, ban check, validation, L4, UDP amp, L7 (16 slots), IP stats, new-source flood, connection tracking, window reset, rate limiting</td></tr><tr><td><code>OPENSHIELD_SYNPROXY</code></td><td>5.15+</td><td>Scalar, rate-based SYN gate (no cookies, no helpers)</td></tr><tr><td><code>OPENSHIELD_GLOBAL_DETECT</code></td><td>6.10+</td><td>SYN/FIN ratio + entropy spoofing detection</td></tr><tr><td><code>OPENSHIELD_ENTROPY</code></td><td>6.10+</td><td>Per-packet entropy bucket tracking</td></tr></tbody></table><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><h3 id="check-enabled-features-at-build-time" tabindex="-1">Check enabled features at build time <a class="header-anchor" href="#check-enabled-features-at-build-time" aria-label="Permalink to &quot;Check enabled features at build time&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ebpf</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Output:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ==&gt; Compiling eBPF program (kernel 6.8.0)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#     Features: -DOPENSHIELD_SYNPROXY</span></span></code></pre></div><p>The Makefile prints which feature flags were detected and passed to the compiler.</p><h3 id="check-available-features-at-runtime" tabindex="-1">Check available features at runtime <a class="header-anchor" href="#check-available-features-at-runtime" aria-label="Permalink to &quot;Check available features at runtime&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Output:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   Kernel: 6.8.0-45-generic</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   SYNPROXY: enabled</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   Global Detection: disabled (need kernel &gt;= 6.10)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   Entropy: disabled (need kernel &gt;= 6.10)</span></span></code></pre></div><p>The CLI reads the compiled-in feature set from the BPF program&#39;s BTF and reports which features are active.</p><h2 id="upgrading-your-kernel" tabindex="-1">Upgrading Your Kernel <a class="header-anchor" href="#upgrading-your-kernel" aria-label="Permalink to &quot;Upgrading Your Kernel&quot;">​</a></h2><ol><li>Upgrade the kernel package (e.g., <code>apt install linux-image-6.10-...</code>)</li><li>Reboot into the new kernel</li><li><strong>Rebuild OpenShield-XDP</strong>:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/openshield/src</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span></span></code></pre></div></li><li>Restart the loader:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield-loader</span></span></code></pre></div></li></ol><p>The rebuilt binary will auto-detect the new kernel version and enable all compatible features.</p><h2 id="base-minimum" tabindex="-1">Base Minimum <a class="header-anchor" href="#base-minimum" aria-label="Permalink to &quot;Base Minimum&quot;">​</a></h2><p>OpenShield-XDP requires <strong>kernel ≥ 5.15</strong> as the absolute minimum. Below 5.15, several core BPF features are unavailable:</p><ul><li><code>BPF_MAP_TYPE_LRU_HASH</code> per-CPU pre-allocation improvements</li><li><code>bpf_ktime_get_boot_ns()</code> precision</li><li>Various verifier improvements needed for the pipeline complexity</li></ul><p>Attempting to build on a kernel below 5.15 will result in compilation errors.</p>`,15))])}const f=n(k,[["render",c]]);export{F as __pageData,f as default};
